#!/usr/bin/env bash
# Versioning tests (AGENTS.md: SemVer 2.0.0, rolling support only).
#
# The root VERSION file is auto-regenerated by tools/version.sh; it must
# always be a well-formed SemVer 2.0.0 version with build metadata, and the
# script must produce the same string it has on disk.
set -u

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
VERSION_FILE="$ROOT/VERSION"

pass=0
fail=0

ok()   { pass=$((pass + 1)); printf 'ok   %s\n' "$1"; }
bad()  { fail=$((fail + 1)); printf 'FAIL %s\n' "$1"; }

if [ ! -f "$VERSION_FILE" ]; then
    echo "FAIL version-file-missing ($VERSION_FILE not found)"
    printf '\n%s passed, %s failed\n' "$pass" "$((fail + 1))"
    exit 1
fi

V="$(cat "$VERSION_FILE")"

# SemVer 2.0.0: MAJOR.MINOR.PATCH[-prerelease][+buildmetadata]
if printf '%s' "$V" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$'; then
    ok "version-is-semver ($V)"
else
    bad "version-is-semver ($V is not a SemVer 2.0.0 version)"
fi

# The channel must be one of dev / beta / stable, and the build metadata must
# carry the short commit sha (AGENTS.md: `+<short-commit-sha>`).
if printf '%s' "$V" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+-(dev|beta|stable)\.[0-9]+\+[0-9a-f]+$'; then
    ok "version-has-channel-and-sha ($V)"
else
    bad "version-has-channel-and-sha ($V lacks a dev|beta|stable channel or the sha)"
fi

# The script must be deterministic: computing the version twice gives the
# same string. `--print` never writes the file, so this test leaves the
# working tree alone. The *file* may legitimately trail HEAD by one commit
# (it records the sha it was stamped at, and a build refreshes it), so the
# test does not require the two to be equal.
P1="$(bash "$ROOT/tools/version.sh" --print 2>/dev/null)"
P2="$(bash "$ROOT/tools/version.sh" --print 2>/dev/null)"
if [ -n "$P1" ] && [ "$P1" = "$P2" ]; then
    ok "version-script-is-deterministic ($P1)"
else
    bad "version-script-is-deterministic ('$P1' vs '$P2')"
fi

# The computed version must also be a well-formed SemVer string.
if printf '%s' "$P1" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+-(dev|beta|stable)\.[0-9]+\+[0-9a-f]+$'; then
    ok "version-script-computes-a-valid-version"
else
    bad "version-script-computes-a-valid-version (got '$P1')"
fi

# An archive tag (e.g. legacy/bootstrap-final) must not be treated as a
# release: on a normal dev commit the computed channel stays `dev`.
BRANCH="$(cd "$ROOT" && git rev-parse --abbrev-ref HEAD 2>/dev/null || echo HEAD)"
HEADTAG="$(cd "$ROOT" && git tag --points-at HEAD 2>/dev/null | grep -E '^v[0-9]+\.[0-9]+\.[0-9]+$' | head -1 || true)"
if [ -z "$HEADTAG" ] && ! printf '%s' "$BRANCH" | grep -Eq '^[0-9]+\.[0-9]+$'; then
    case "$P1" in
        *-dev.*) ok "archive-tags-do-not-mark-a-release ($P1)" ;;
        *) bad "archive-tags-do-not-mark-a-release (got '$P1')" ;;
    esac
fi

# The compiler must report the same version.
if [ -x "$ROOT/build/harmony" ]; then
    OUT="$(cd "$ROOT" && ./build/harmony --version 2>/dev/null)"
    case "$OUT" in
        *" $V") ok "compiler-reports-version ($OUT)" ;;
        *) bad "compiler-reports-version (got '$OUT', want '$V')" ;;
    esac
else
    printf 'skip compiler-reports-version (harmony not built)\n'
fi

printf '\n%s passed, %s failed\n' "$pass" "$fail"
[ "$fail" -eq 0 ]
